#!/usr/bin/env python3
"""Rewrites the machine-generated pin region of a Nix file.

    pin_block.py <nix-file> <block-file>

The region is delimited by the marker lines

    # >>> generated by update.py
    # <<< generated by update.py

(any indentation; the marker lines themselves are preserved). Used by
packages/opencode2/update.py and packages/opencode-desktop/update.py so their
version/hash pins can be bumped mechanically instead of by hand.
"""
import pathlib
import re
import sys

MARKER_OPEN = "# >>> generated by update.py"
MARKER_CLOSE = "# <<< generated by update.py"

_PATTERN = re.compile(
    rf"(?m)^( *# {re.escape(MARKER_OPEN[2:])}\n)[\s\S]*?( *# {re.escape(MARKER_CLOSE[2:])}\n)"
)


def rewrite(target, block):
    """Splice `block` between the markers of `target`; returns True if changed."""
    target = pathlib.Path(target)
    src = target.read_text()
    new, count = _PATTERN.subn(lambda m: m.group(1) + block + m.group(2), src)
    if count != 1:
        raise RuntimeError(f"expected exactly one generated block in {target}, found {count}")
    if new == src:
        print(f"{target.name}: already up to date")
        return False
    target.write_text(new)
    print(f"{target.name}: rewritten")
    return True


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    rewrite(sys.argv[1], pathlib.Path(sys.argv[2]).read_text())
